    std::vector<std::size_t>parentNode(graph.size(),graph.size()),parentArc(graph.size(),0U);std::queue<std::size_t>q;parentNode[source]=source;q.push(source);
    while(!q.empty()&&parentNode[sink]==graph.size()){const auto u=q.front();q.pop();for(std::size_t ai=0;ai<graph[u].size();++ai){const auto&e=graph[u][ai];if(e.capacity<=EInt(0)||parentNode[e.to]!=graph.size())continue;parentNode[e.to]=u;parentArc[e.to]=ai;q.push(e.to);if(e.to==sink)break;}}
    if(parentNode[sink]==graph.size())return std::nullopt;
    EInt delta=init.need-total;for(auto v=sink;v!=source;v=parentNode[v])delta=exact_min(delta,graph[parentNode[v]][parentArc[v]].capacity);if(delta<=EInt(0))return std::nullopt;
    for(auto v=sink;v!=source;v=parentNode[v]){auto&e=graph[parentNode[v]][parentArc[v]];auto&r=graph[v][e.reverse];e.capacity-=delta;r.capacity+=delta;if(e.original)flow[*e.original]+=e.forward?delta:-delta;}
