  if(cert.spans!=expectedSpans)return validation_error("certificate span membership mismatch");
  const auto expectedInc=component_incidences(p,c);if(cert.incidences!=expectedInc)return validation_error("certificate incidence payload mismatch");
  std::vector<ConformityBoundaryIncidenceId> expectedIds;for(const auto&i:expectedInc)expectedIds.push_back(i.id);
  if(cert.incidenceIds!=expectedIds)return validation_error("certificate incidence identity mismatch");
  if(cert.sourceDigest!=topology.source_digest()||cert.networkDigest!=topology.network_digest()||cert.cutGraphDigest!=topology.cut_graph_digest()||cert.topologyPlanDigest!=topology.semantic_digest()||cert.targetMetricDigest!=p.metric||cert.normalizedProblemDigest!=p.digest)
    return validation_error("certificate binding mismatch");

