  if(cert.finiteCapU!=U||cert.radixQ!=Q||cert.lexicographicScaleL!=L)return validation_error("certificate U/Q/L mismatch");
  std::map<ConformitySpanId,EInt> counts;std::vector<EInt> finalCounts;ConformityObjectiveValue objective;objective.primaryDeviation=EInt(0);objective.scalarValue=EInt(0);
  for(std::size_t li=0;li<E;++li){auto s=c.spans[li];const auto&e=cert.schedule[li];if(e.span!=p.spans[s].id||e.preferredCount!=p.preferred[s]||e.supportPieces!=p.spans[s].supportPieces||e.count<EInt(1)||e.count>U)return validation_error("certificate schedule mismatch");counts.emplace(e.span,e.count);finalCounts.push_back(e.count);const EInt deviation=(e.count-p.preferred[s]).abs(),lex=exact_power(Q,E-li-1U);objective.primaryDeviation+=deviation;objective.canonicalCounts.push_back(e.count);objective.scalarValue+=L*deviation+lex*e.count;}
