  for(std::size_t li=0;li<V;++li){if(cert.rows[li].row!=p.rows[c.rows[li]])return validation_error("certificate row identity mismatch");EInt signedBalance(0),unsignedBoundary(0);for(const auto&i:expectedInc)if(i.id.region==cert.rows[li].row.region&&i.family==cert.rows[li].row.family){signedBalance+=EInt(static_cast<int>(i.sign))*counts.at(i.span);unsignedBoundary+=counts.at(i.span);}if(signedBalance!=EInt(0)||!is_even(unsignedBoundary)||cert.rows[li].signedBalance!=signedBalance||cert.rows[li].unsignedBoundaryCount!=unsignedBoundary||!cert.rows[li].parityEven)return validation_error("certificate balance/parity mismatch");}

