  for(std::size_t i=0;i<edges.size();++i)if(w.terminalCounts[i]<edges[i].lower||w.terminalCounts[i]>edges[i].upper)return validation_error("terminal witness violates exact bounds");
  auto graph=refinement_graph(solverRows,edges,w.terminalCounts,L);
  if(w.biMcfEdgeCount!=graph.biEdges||w.bMatchingNodeCount!=graph.bNodes||w.bMatchingEdgeCount!=graph.bEdges||w.wpmNodeCount!=graph.wNodes||w.wpmEdges.size()!=graph.wedges.size()||w.nodeDualValues.size()!=graph.wNodes)return validation_error("terminal witness graph dimensions mismatch");
  expectedPeakNodes=std::max(expectedPeakNodes,graph.wNodes);expectedPeakEdges=std::max(expectedPeakEdges,graph.wedges.size());
  if(ledger.peakMatchingNodeCount!=expectedPeakNodes||ledger.peakMatchingEdgeCount!=expectedPeakEdges)return validation_error("certificate WorkLedger peak matching dimensions mismatch");
  if(ledger.maximumObservedExactIntegerBitWidth!=expected_overall_width(ledger,w))return validation_error("certificate WorkLedger maximum exact width mismatch");
  for(std::size_t i=0;i<graph.wedges.size();++i)if(w.wpmEdges[i].first!=graph.wedges[i].a||w.wpmEdges[i].second!=graph.wedges[i].b||w.wpmEdges[i].weight!=graph.wedges[i].weight)return validation_error("terminal witness graph identity mismatch");
  if(w.terminalProblemDigest!=terminal_digest(solverRows,w.terminalCounts,graph.wedges))return validation_error("terminal problem digest mismatch");
  if(w.matchingDualScale!=4)return validation_error("terminal matching dual scale mismatch");
