  for(std::size_t wi=0;wi<w.wpmEdges.size();++wi)if(w.wpmEdges[wi].matched){const auto&e=graph.wedges[wi];if(e.a>=graph.wNodes||e.b>=graph.wNodes)return validation_error("matched WPM edge endpoint out of range");++matchedDegree[e.a];++matchedDegree[e.b];primal+=e.weight;if(e.bedge)++bflow[*e.bedge];}
